'use strict';
const $=s=>document.querySelector(s);
const KEY='form-fuel-v1';
const defaults=()=>({plan:null,meals:[],reminder:{enabled:false,time:'18:00',percent:70},notified:''});
let state=defaults(),storageProblem=false;
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);state={...defaults(),...saved};if(!Array.isArray(state.meals))throw Error('Invalid journal');}}catch(e){storageProblem=true;state=defaults();}
let muscle='biceps',partIndex=0,view='both',mealPhoto='',ingredients=[],photoWorker=null,photoBusy=false;
let currentDay=dateKey(),fuelDay=dateKey(),editingMealId=null;
window.fuelDay=()=>fuelDay;
function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function timeKey(d=new Date()){return `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function safe(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function number(n){return Number(n).toLocaleString(undefined,{maximumFractionDigits:1});}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));document.dispatchEvent(new Event('fuel:changed'));return true;}catch(e){toast('Your browser could not save this change. Export a backup or free some storage.');return false;}}
let toastTimer;
function toast(message,duration=4500){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),duration);}
function openDialog(id){$(id).showModal();}
document.querySelectorAll('.close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
function info(title,html){$('#infoTitle').textContent=title;$('#infoBody').innerHTML=html;openDialog('#infoDialog');}
$('#muscleSelect').innerHTML=Object.entries(MUSCLES).map(([key,m])=>`<option value="${key}">${m.name}</option>`).join('');
$('#muscleSelect').value=muscle;
$('#muscleGroupCount').textContent=`${Object.keys(MUSCLES).length} muscle groups`;
$('#muscleSelect').addEventListener('change',e=>selectMuscle(e.target.value));
const liftIcon='<svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><circle cx="20" cy="8" r="3"/><path d="M20 12v12m0-8-8 4-5-5m13 1 8 4 5-5M20 24l-6 10m6-10 6 10M4 12v6m3-7v8m26-8v8m3-7v6"/></svg>';
function selectMuscle(key,keepView=false){muscle=key;partIndex=0;$('#muscleSelect').value=key;if(!keepView&&view!=='both'){view=['back','glutes','hamstrings','triceps'].includes(key)?'back':'front';}renderMuscle();renderMap();}
function anatomyNotes(text){return '<ul class="brief-notes">'+String(text).split(/(?<=[.!?])\s+/).map(s=>'<li>'+safe(s)+'</li>').join('')+'</ul>';}
function renderMuscle(){const m=MUSCLES[muscle],p=m.parts[partIndex];$('#muscleName').textContent=m.name;$('#muscleLatin').textContent=m.latin;$('#mapLabel').innerHTML=`${safe(m.name)} <span>↗</span>`;$('#partTabs').innerHTML=m.parts.map((p,i)=>`<button class="${partIndex===i?'selected':''}" aria-pressed="${partIndex===i}" data-part="${i}">${safe(p.name)}</button>`).join('');$('#partTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{partIndex=Number(b.dataset.part);renderMuscle();});$('#partName').textContent=p.name;$('#partDescription').innerHTML=anatomyNotes(p.description);const moves=[...new Set(p.moves)];$('#exerciseCount').textContent=`${moves.length} suggested exercises`;$('#exercises').innerHTML=moves.map(key=>{const e=EXERCISES[key];return `<button class="exercise" data-exercise="${key}"><span class="exercise-icon">${liftIcon}</span><div><h4>${safe(e.name)}</h4><small>${safe(e.sets)} &nbsp;·&nbsp; ${safe(e.equipment.split(' · ')[0])}</small></div><span class="arrow">↗</span></button>`;}).join('');$('#exercises').querySelectorAll('button').forEach(b=>b.onclick=()=>{const e=EXERCISES[b.dataset.exercise];info(e.name,`${ExerciseVisuals.render(b.dataset.exercise)}<div class="instruction-meta">${safe(e.sets)}<br>${safe(e.equipment)}</div><h3>How to do it</h3><ol>${e.steps.map(s=>`<li>${safe(s)}</li>`).join('')}</ol><p>${safe(e.tip)}</p><p class="tiny">Start light. Stop if you feel sharp pain. These are starting suggestions, not an individual training prescription.</p>`);});$('#growthText').innerHTML=anatomyNotes(m.growth);}
function renderMap(){
 const sides=view==='both'?['front','back']:[view];
 const wrapper=$('#anatomyViews');wrapper.classList.toggle('both',view==='both');
 wrapper.innerHTML=sides.map((side,i)=>`<figure class="anatomy-view" data-side="${side}"><svg id="${i?'bodyMapBack':'bodyMap'}" class="body-map-figure" data-side="${side}" viewBox="0 0 340 540" role="group" aria-label="${side==='front'?'Front':'Back'} interactive muscle map">${AnatomyMap.create(muscle,side,side)}</svg><figcaption>${side==='front'?'Front · anterior':'Back · posterior'}</figcaption></figure>`).join('');
 wrapper.querySelectorAll('[data-muscle]').forEach(el=>{
  const activate=()=>{const key=el.dataset.muscle,label=el.getAttribute('aria-label'),side=el.closest('svg').dataset.side;selectMuscle(key,true);const region=[...wrapper.querySelectorAll(`svg[data-side="${side}"] [data-muscle="${key}"]`)].find(next=>next.getAttribute('aria-label')===label);region?.focus({preventScroll:true});};
  el.onclick=activate;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}};
 });
 ['front','back','both'].forEach(side=>{const b=$('#'+side+'View');b.classList.toggle('selected',view===side);b.setAttribute('aria-pressed',String(view===side));});
}
$('#frontView').onclick=()=>{view='front';if(['back','glutes','hamstrings','triceps'].includes(muscle))selectMuscle('biceps',true);else renderMap();};$('#backView').onclick=()=>{view='back';if(['chest','biceps','abs','obliques','quads'].includes(muscle))selectMuscle('back',true);else renderMap();};
$('#bothView').onclick=()=>{view='both';renderMap();};
function calculatePlan(data){return NutritionCore.calculate(data);}
function readPlanForm(){const f=new FormData($('#planForm'));return {goal:f.get('goal'),activity:Number(f.get('activity')),age:state.profile?.dob?(ProfileCore.ageAt(state.profile.dob,dateKey())??Number(f.get('age'))):Number(f.get('age')),sex:f.get('sex'),height:Number(f.get('height')),weight:Number(f.get('weight'))};}
function openPlan(){const form=$('#planForm');if(state.plan)Object.entries(state.plan).forEach(([k,v])=>{if(form.elements.namedItem(k))form.elements.namedItem(k).value=v;});window.AccountProfile?.fillPlan(form);previewPlan();openDialog('#planDialog');}
function previewPlan(){const data=readPlanForm();if(data.weight>=35&&data.height>=120&&data.age>=18){const p=calculatePlan(data);$('#planPreview').textContent=`${number(p.calories)} kcal · ${p.protein} g protein · ${p.carbs} g carbs · ${p.fat} g fat per day`;}else $('#planPreview').textContent='Enter your details to preview your daily targets.';}
$('#planForm').addEventListener('input',previewPlan);$('#planForm').onsubmit=e=>{e.preventDefault();const previous=state.plan;state.plan=calculatePlan(readPlanForm());const oldProfile=state.profile;if(oldProfile)state.profile={...oldProfile,...readPlanForm(),updatedAt:new Date().toISOString()};if(!save()){state.plan=previous;state.profile=oldProfile;return;}$('#planDialog').close();renderNutrition();toast('Your nutrition blueprint is saved on this device.');checkReminder();};$('#editTargets').onclick=openPlan;$('#profileButton').onclick=openPlan;
function totals(date=dateKey()){return state.meals.filter(m=>m.date===date).reduce((a,m)=>({calories:a.calories+Number(m.calories),protein:a.protein+Number(m.protein),carbs:a.carbs+Number(m.carbs),fat:a.fat+(Number(m.fat)||0)}),{calories:0,protein:0,carbs:0,fat:0});}
function renderNutrition(){
 const t=totals(fuelDay);let p=state.plan;try{const versions=JSON.parse(localStorage.getItem('form-fuel-calendar-v1')||'{}').targets||[];if(fuelDay<dateKey()){const old=versions.filter(v=>v.from<=fuelDay).sort((a,b)=>a.from.localeCompare(b.from)).at(-1);if(old)p={...p,...old.values,fat:old.values.fat??null};}}catch{}
 $('#goalBadge').textContent=fuelDay<dateKey()?'Past day':p?({gain:'Build muscle',maintain:'Maintain weight',lose:'Lose body fat',strength:'Gain strength'}[p.goal]):'Set your goal';
 $('#planStatus').textContent=p?'Your saved daily targets':'Your plan starts here';
 const previous=[...$('#rings').querySelectorAll('.macro-fill')].map(bar=>bar.style.width);
 const icons={fat:'<path d="M12 3C9 8 5 12 5 16a7 7 0 0 0 14 0c0-4-4-8-7-13Z"/>',calories:'<path d="M14 3c1 6-5 6-3 11 2-1 3-3 3-3 5 4 5 10-2 10-8 0-10-9-5-13 0 4 2 4 2 4-1-5 5-9 5-9Z"/>',protein:'<path d="m5 5 14 14M3 8l5-5M16 21l5-5M2 5l3-3M19 22l3-3M7 11l4-4M13 17l4-4"/>',carbs:'<path d="M12 21V4M12 9C6 9 5 5 5 3c5 0 7 3 7 6Zm0 6c-6 0-7-4-7-6 5 0 7 3 7 6Zm0-3c6 0 7-4 7-6-5 0-7 3-7 6Zm0 6c6 0 7-4 7-6-5 0-7 3-7 6Z"/>'};
 $('#rings').innerHTML=[['calories','Calories','kcal'],['protein','Protein','g'],['carbs','Carbs','g'],['fat','Fat','g']].map(([key,label,unit],i)=>{
  const unknown=key==='fat'&&state.meals.some(m=>m.date===fuelDay&&m.fat==null);const target=p?.[key]||0,fraction=target&&!unknown?Math.min(1,t[key]/target):0,remaining=Math.max(0,target-t[key]);
  const status=unknown?'Some meals have no fat recorded':!target?'Set a target to begin':t[key]>target?number(t[key]-target)+' '+unit+' over target':number(remaining)+' '+unit+' remaining';
  const percent=target?Math.round(t[key]/target*100):0;
  return '<div class="macro-card macro-'+key+'"><div class="macro-fill" style="width:'+(previous[i]||'0%')+'" data-width="'+fraction*100+'%"></div><span class="macro-icon" aria-hidden="true"><svg viewBox="0 0 24 24">'+icons[key]+'</svg></span><div class="macro-copy"><h4>'+label+'</h4><div class="macro-amount"><strong>'+(unknown?'—':number(t[key]))+'</strong> <span>/ '+(target?number(target):'—')+' '+unit+'</span></div><p>'+status+'</p></div><span class="macro-percent">'+(target?percent+'%':'—')+'</span><div class="macro-accessible" role="progressbar" aria-label="'+label+' daily target" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+Math.min(100,percent)+'" aria-valuetext="'+number(t[key])+' '+unit+' consumed; '+status+'"></div></div>';
 }).join('');
 requestAnimationFrame(()=>requestAnimationFrame(()=>$('#rings').querySelectorAll('.macro-fill').forEach(bar=>bar.style.width=bar.dataset.width)));
 let note='Set a personal target, then add your first meal.';
 if(p){if(!t.calories)note='A fresh start. Add your first meal and make today count.';else if(t.protein>=p.protein&&t.calories>=p.calories)note='Your calorie and protein targets are met. Listen to your hunger and recovery.';else note=number(Math.max(0,p.protein-t.protein))+' g protein left for this day. Every balanced meal moves you forward.';}
 $('#dailyNote').innerHTML='<span aria-hidden="true">✧</span> '+safe(note);
}
function renderJournal(){const day=$('#journalDate').value;const meals=state.meals.filter(m=>m.date===day).sort((a,b)=>a.time.localeCompare(b.time));if(!meals.length){$('#mealList').innerHTML='<div class="empty-state"><span>♧</span><div><h3>A fresh page for your fuel.</h3><p>No meals logged for this day. Your next meal is a good place to start.</p></div><button class="secondary" id="emptyAddMeal">+ Add meal</button></div>';$('#emptyAddMeal').onclick=openMeal;return;}$('#mealList').innerHTML=meals.map(m=>`<div class="meal-row">${m.photo&&/^data:image\/(jpeg|png|webp);base64,/.test(m.photo)?`<img class="meal-thumb" src="${safe(m.photo)}" alt="${safe(m.name)}">`:'<span class="meal-thumb">♧</span>'}<div><h4>${safe(m.name)}</h4><small>${safe(m.time)} · ${m.estimated?'Food estimate':'Manual entry'}</small></div><div class="meal-macros"><div>${number(m.calories)}<small>kcal</small></div><div>${number(m.protein)} g<small>protein</small></div><div>${number(m.carbs)} g<small>carbs</small></div></div><button class="delete-meal" data-id="${safe(m.id)}" aria-label="Delete ${safe(m.name)}">×</button></div>`).join('');$('#mealList').querySelectorAll('.delete-meal').forEach(b=>b.onclick=()=>{const i=state.meals.findIndex(m=>m.id===b.dataset.id);if(i<0)return;const removed=state.meals.splice(i,1)[0];if(!save()){state.meals.splice(i,0,removed);return;}renderNutrition();renderJournal();toast('Meal removed from your journal.');});}
$('#journalDate').value=dateKey();$('#journalDate').onchange=renderJournal;
$('#foodSelect').innerHTML=FOODS.map((f,i)=>['Fried rice','Chicken rice','Pizza','Hamburger','French fries','Sushi','Lentil curry'].includes(f.name)?'':`<option value="${i}">${safe(f.name)}</option>`).join('');
function openMeal(){editingMealId=null;const f=$('#mealForm');f.reset();ingredients=[];mealPhoto='';$('#mealPreview').hidden=true;$('#mealPreview').removeAttribute('src');$('#analyzePhoto').hidden=true;$('#photoSuggestions').innerHTML='';$('#ingredients').innerHTML='';$('#photoStatus').textContent='On-device recognition · first download about 150 MB. Confirm food and portions.';f.elements.date.value=$('#journalDashboardDialog')?.open?$('#journalDate').value:fuelDay;f.elements.time.value=timeKey();openDialog('#mealDialog');document.dispatchEvent(new Event('meal:opened'));}
$('#addMeal').onclick=openMeal;
function updateIngredients(){window.MealComposer?.clearEstimate();const t=ingredients.reduce((sum,i)=>{const f=FOODS[i.food];return {calories:sum.calories+f.calories*i.grams/100,protein:sum.protein+f.protein*i.grams/100,carbs:sum.carbs+f.carbs*i.grams/100};},{calories:0,protein:0,carbs:0});const f=$('#mealForm');f.elements.calories.value=Math.round(t.calories);f.elements.protein.value=t.protein.toFixed(1);f.elements.carbs.value=t.carbs.toFixed(1);f.elements.fat.value='';f.elements.name.value=ingredients.map(i=>FOODS[i.food].name).join(' + ').slice(0,100);$('#ingredients').innerHTML=ingredients.map((i,n)=>`<div>${safe(FOODS[i.food].name)} · ${i.grams} g <button type="button" data-remove="${n}" aria-label="Remove ${safe(FOODS[i.food].name)}">×</button></div>`).join('');$('#ingredients').querySelectorAll('button').forEach(b=>b.onclick=()=>{ingredients.splice(Number(b.dataset.remove),1);updateIngredients();});}
$('#addFood').onclick=()=>{const grams=Number($('#foodGrams').value);if(!Number.isFinite(grams)||grams<1||grams>3000){toast('Choose a portion between 1 and 3,000 grams.');return;}ingredients.push({food:Number($('#foodSelect').value),grams});updateIngredients();};
$('#mealForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const meal={id:editingMealId||crypto.randomUUID(),name:String(f.get('name')).trim(),date:f.get('date'),time:f.get('time'),calories:Number(f.get('calories')),protein:Number(f.get('protein')),carbs:Number(f.get('carbs')),fat:f.get('fat')===''?null:Number(f.get('fat')),photo:mealPhoto,estimated:ingredients.length>0||Boolean(window.MealComposer?.current),estimate:window.MealComposer?.current||null,ingredients:ingredients.map(i=>({...i})),createdAt:new Date().toISOString()};if(!meal.name||![meal.calories,meal.protein,meal.carbs].every(Number.isFinite)){toast('Enter a meal name and valid nutrition values.');return;}const before=state.meals.slice();if(editingMealId){const i=state.meals.findIndex(m=>m.id===editingMealId);meal.createdAt=state.meals[i].createdAt;state.meals[i]=meal;}else state.meals.push(meal);if(!save()){state.meals=before;return;}$('#mealDialog').close();fuelDay=meal.date;$('#fuelDate').value=meal.date;$('#journalDate').value=meal.date;renderNutrition();renderJournal();document.dispatchEvent(new Event('meals:render'));document.dispatchEvent(new Event('fuel:date'));toast('Meal saved. Your daily fuel is up to date.');checkReminder();};
async function handlePhoto(e){const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Please choose an image file.');return;}if(file.size>15*1024*1024){toast('Choose a photo smaller than 15 MB.');return;}if(photoBusy)stopAnalysis();try{const bitmap=await createImageBitmap(file);const ratio=Math.min(1,640/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*ratio));c.height=Math.max(1,Math.round(bitmap.height*ratio));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();mealPhoto=c.toDataURL('image/jpeg',.72);$('#mealPreview').src=mealPhoto;$('#mealPreview').hidden=false;$('#analyzePhoto').hidden=false;$('#photoSuggestions').innerHTML='';$('#photoStatus').textContent='Photo ready. Identify food, then confirm ingredients and grams.';}catch(e){toast('This image could not be opened. Try a JPG or PNG.');}}
$('#photoUpload').onchange=handlePhoto;$('#cameraUpload').onchange=handlePhoto;
function stopAnalysis(){photoWorker?.terminate();photoWorker=null;photoBusy=false;$('#analyzePhoto').textContent='Identify food in this photo ↗';}
$('#mealDialog').addEventListener('close',()=>{if(photoBusy){stopAnalysis();}});
$('#analyzePhoto').onclick=()=>{if(photoBusy){stopAnalysis();$('#photoStatus').textContent='Image recognition cancelled. You can still add foods and portions below.';return;}if(!mealPhoto)return;photoBusy=true;$('#analyzePhoto').textContent='Cancel image recognition';$('#photoStatus').textContent='Preparing local image recognition. The first model download may take a few minutes…';$('#photoSuggestions').innerHTML='';try{if(!photoWorker)photoWorker=new Worker('photo-worker.js',{type:'module'});photoWorker.onmessage=({data})=>{if(data.type==='progress'){$('#photoStatus').textContent=data.message;}if(data.type==='result'){photoBusy=false;$('#analyzePhoto').textContent='Identify food again ↗';if(data.results[0]?.label==='not food'){$('#photoStatus').textContent='This photo may not show food. Try a clear meal photo, or choose foods manually.';return;}const results=data.results.filter(r=>r.label!=='not food').slice(0,3);$('#photoStatus').textContent='Choose a likely food and confirm grams. Add oils, sauces and sides separately.';$('#photoSuggestions').innerHTML=results.map(r=>`<button type="button" data-food="${FOODS.findIndex(f=>f.name===r.label)}">${safe(r.label)} ↗</button>`).join('');$('#photoSuggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('#ingredientTools').open=true;$('#foodSelect').value=b.dataset.food;$('#foodGrams').focus();toast('Confirm the portion in grams, then tap + Add.');});}if(data.type==='error'){stopAnalysis();$('#photoStatus').textContent='Image recognition could not load. Check your connection or browser support and retry. You can select foods below to estimate this meal now.';}};photoWorker.onerror=()=>{stopAnalysis();$('#photoStatus').textContent='Image recognition is unavailable in this browser. Add food and grams below, or enter nutrition values manually.';};photoWorker.postMessage({photo:mealPhoto,labels:[...FOODS.map(f=>f.name),'not food']});}catch(e){stopAnalysis();$('#photoStatus').textContent='Image recognition is unavailable here. Select foods and portions below to continue.';}};
function reminderUI(){const r=state.reminder;$('#reminderSummary').textContent=r.enabled?`Daily at ${r.time} · A nudge if calories or protein are below ${r.percent}% of your target. Keep this site open.`:'Set a check-in time and we’ll let you know if your fuel is falling behind.';$('#reminderButton').textContent=r.enabled?'Edit reminders ↗':'Set reminders ↗';}
$('#reminderButton').onclick=()=>{const f=$('#reminderForm');f.elements.enabled.checked=state.reminder.enabled;f.elements.time.value=state.reminder.time;f.elements.percent.value=state.reminder.percent;$('#notificationStatus').textContent=('Notification'in window)?`Browser notifications: ${Notification.permission}. Check-ins run while this site is open, using your device’s local time.`:'This browser does not support notifications. You can still receive in-app check-ins while this site is open.';openDialog('#reminderDialog');};
$('#notificationButton').onclick=async()=>{if(!('Notification'in window)){toast('Browser notifications are unavailable. In-app reminders still work.');return;}try{const p=await Notification.requestPermission();$('#notificationStatus').textContent=p==='granted'?'Browser notifications enabled. Keep the site open for scheduled check-ins.':p==='denied'?'Notifications blocked. You can enable them in browser settings; in-app reminders still work.':'Permission was not granted. In-app reminders still work.';}catch(e){toast('Notifications are unavailable here. In-app reminders still work.');}};
$('#reminderForm').onsubmit=e=>{e.preventDefault();const f=e.target;const old={...state.reminder},oldNotified=state.notified;state.reminder={enabled:f.elements.enabled.checked,time:f.elements.time.value,percent:Number(f.elements.percent.value)};state.notified='';if(!save()){state.reminder=old;state.notified=oldNotified;return;}$('#reminderDialog').close();reminderUI();toast(state.reminder.enabled?'Daily check-in saved. Keep the site open to receive your nudge.':'Daily check-in paused.');checkReminder();};
function checkReminder(){const r=state.reminder,p=state.plan;if(!r.enabled||!p||timeKey()<r.time||state.notified===dateKey())return;const t=totals(),low=[];if(t.calories<p.calories*r.percent/100)low.push(`${number(Math.max(0,p.calories-t.calories))} kcal`);if(t.protein<p.protein*r.percent/100)low.push(`${number(Math.max(0,p.protein-t.protein))} g protein`);if(!low.length)return;state.notified=dateKey();save();const message=`Your fuel check-in: ${low.join(' and ')} left to your full daily target. Time for a meal or snack?`;toast(message,15000);if('Notification'in window&&Notification.permission==='granted'){try{new Notification('Form & Fuel · Daily check-in',{body:message,tag:'form-fuel-daily'});}catch(e){/* In-app reminder remains visible. */}}}
$('#exportButton').onclick=()=>{const blob=new Blob([JSON.stringify({app:'Form & Fuel',exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`form-and-fuel-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);toast('Your saved plan and journal have been exported.');};
const sources='<h3>Evidence & further reading</h3><p><a href="https://www.ncbi.nlm.nih.gov/books/NBK519538/" target="_blank" rel="noopener">Biceps anatomy · NCBI / StatPearls</a><br><a href="https://www.sciencedirect.com/science/article/pii/S0002916523166986" target="_blank" rel="noopener">Mifflin–St Jeor energy equation · original study</a><br><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5477153/" target="_blank" rel="noopener">Protein and exercise · ISSN position stand</a></p>';
$('#learnButton').onclick=()=>info('Understand. Train. Recover.','<p>Train consistently, progress gradually and recover between sessions.</p><p>Leave 1–3 repetitions in reserve. Add reps or weight gradually.</p><p>Exercise position changes emphasis; muscle heads still work together.</p>'+sources);
$('#aboutButton').onclick=()=>info('Your data & your estimates','<h3>Saved on this device</h3><p>Google sign-in enables cloud saves. Signed-out data stays in this browser. Check sync status and download a backup.</p><h3>Food photo recognition</h3><p>Photos are processed on-device. Confirm ingredients and portions; recognition cannot measure oils, sauces or portion size.</p><h3>A starting point for nutrition</h3><p>Adult estimates use Mifflin–St Jeor. Review your trends. Not intended for pregnancy or medical diets.</p><h3>Reminders</h3><p>Reminders check calories and protein once daily. Keep the site open; notifications need permission.</p>'+sources);
function renderDate(){$('#todayDate').textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date());}
document.querySelectorAll('.header nav a').forEach(a=>a.onclick=()=>{document.querySelectorAll('.header nav a').forEach(n=>n.classList.toggle('active',n===a));});
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;document.querySelectorAll('.header nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${entry.target.id}`));}},{rootMargin:'-15% 0px -55% 0px'});['explore','routines','calendar','nutrition','journal'].forEach(id=>observer.observe(document.getElementById(id)));}
setInterval(()=>{if(dateKey()!==currentDay){const wasToday=$('#journalDate').value===currentDay;currentDay=dateKey();if(wasToday)$('#journalDate').value=currentDay;renderDate();renderNutrition();renderJournal();}checkReminder();},15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){renderNutrition();checkReminder();}});
renderDate();renderMuscle();renderMap();renderNutrition();renderJournal();reminderUI();setTimeout(checkReminder,1200);if(storageProblem)setTimeout(()=>toast('Saved data could not be read. Browser storage may be unavailable; export your journal after making changes.',10000),1500);
